import * as React from "react"
import type { ComponentType } from "react"

const clipName = "Lotus Bloom Web 10MB.001"

// Lightweight hologram is rendered by LotusHologramRuntime.
const lotusMaterial = { preset: "none", override: false, transmission: 0, wireframe: false }
const lotusEnvironment = { enabled: false, transparent: true, showBg: false, customUrl: "", ambient: 0, dirIntensity: 0 }
const lotusEffects = { bloom: false, chromAberr: false, filmGrain: false, ssao: false, dof: false, fxaa: false, exposure: 1 }
const lotusRimLights: any[] = []
const listeners = new Set<() => void>()
let started = false
let owners = 0

function notify() {
    listeners.forEach((listener) => listener())
}
function subscribe(listener: () => void) {
    listeners.add(listener)
    return () => { listeners.delete(listener) }
}
function startOnce() {
    if (started) return
    started = true
    notify()
}
function usePageLifetime() {
    React.useEffect(() => {
        owners += 1
        return () => {
            owners -= 1
            if (owners === 0) {
                started = false
                notify()
            }
        }
    }, [])
}

// Only the HOA SEN loading instance is connected to this callback.
export function withLotusLoadingComplete(Component: ComponentType<any>): ComponentType<any> {
    return React.forwardRef<any, any>(function LotusLoadingComplete(props, ref) {
        usePageLifetime()
        const onComplete = React.useCallback(() => {
            startOnce()
            props.onComplete?.()
        }, [props.onComplete])
        return <Component {...props} ref={ref} audience={props.breakpoint ?? props.audience ?? "Desktop"} onComplete={onComplete} />
    })
}

// Keep the clip at time zero until the loading dialog has closed.
// The existing runtime uses LoopOnce + clampWhenFinished to hold the last frame.
export function withLotusLoadingAnimation(Component: ComponentType<any>): ComponentType<any> {
    return React.forwardRef<any, any>(function LotusLoadingAnimation(props, ref) {
        usePageLifetime()
        const hasStarted = React.useSyncExternalStore(subscribe, () => started, () => false)
        const interaction = React.useMemo(() => ({
            ...props.interaction,
            autoRotate: true,
            rotateSpeed: 0.5,
            float: false,
            mouseRotate: false,
            orbit: false,
            animClip: clipName,
            animSpeed: hasStarted ? 1 : 0,
            animLoopMode: "once",
        }), [props.interaction, hasStarted])
        const material = React.useMemo(() => ({ ...props.material, ...lotusMaterial }), [props.material])
        const environment = React.useMemo(() => ({ ...props.environment, ...lotusEnvironment }), [props.environment])
        const effects = React.useMemo(() => ({ ...props.effects, ...lotusEffects }), [props.effects])
        return <Component
            {...props}
            ref={ref}
            material={material}
            environment={environment}
            effects={effects}
            extraLights={lotusRimLights}
            transition={{ ...props.transition, enabled: false }}
            interaction={interaction}
            animClip={clipName}
            animName={clipName}
            animSpeed={hasStarted ? 1 : 0}
            animLoopMode="once"
            animLoop="once"
        />
    })
}
